html`&lt;p style="font-size: 3rem; text-align: center; font-weight: bold; color: #E69F00; margin: 0;"&gt;${d3.mean(filtered, d =&gt; d.clues)?.toFixed(1)}&lt;/p&gt;`














Plot.rectY(filtered, 
  Plot.binX(
    {y: "count"}, 
    {x: "date", fill: by_variable, thresholds: 'auto'}
  ))
  .plot({
    color: {legend: true},
    marks: [
      Plot.frame(),
    ]
  }
)







Plot.lineY(filtered, 
    Plot.binX(
      {y: "mean", interval: d3.timeMonth}, 
      {x: "date", y: "rating", strokeWidth: 3}
    )
  )
  .plot({
    color: {legend: false},
    y: {label: "Rating"}, 
    marks: [
      Plot.frame(),
      Plot.dot(filtered, 
      {x: "date", y: "rating", color: by_variable, fill: by_variable}
    )
    ]
  }
)







